with parsed as (select id, host, level, latency_ms, context['version'] as version, coalesce(context['trace'], 'none') as trace_or_default, size(context) as num_context, get_json_object(payload_json, '$.user.id') as user_id, cast((status_code & 1) != 0 as int) as flag_bit1 from app_logs) select *, ntile(5) over (order by num_context desc, id) num_context_bucket, rank() over (order by latency_ms desc nulls last) latency_ms_rank, first_value(latency_ms) ignore nulls over (order by latency_ms, id rows between unbounded preceding and current row) first_known_latency_ms from parsed;
